84	    private static final int MAX_OWNERS_PER_CITY = 50;
85	
86	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
87	    private static final int MAX_OWNERS_PER_DAY = 100;
88	
89	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
90	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
91	
92	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
93	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
94	
95	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
96	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
