162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        List<String> missingFields = new ArrayList<>();
166	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
167	            missingFields.add("firstName");
168	        }
169	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
170	            missingFields.add("lastName");
171	        }
172	        // Normalize the address up front; the required-field check rejects it when it is blank
173	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
174	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
175	        if (!StringUtils.hasText(normalizedAddress)) {
176	            missingFields.add("address");
177	        }
178	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
179	            missingFields.add("city");
180	        }
181	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
182	            missingFields.add("telephone");
183	        }
184	        if (!missingFields.isEmpty()) {
185	            throw new InvalidRequestException(missingFields);
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
189	        // Store (and later return) the normalized address computed above.
190	        owner.setAddress(normalizedAddress);
191	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
192	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
193	        owner.setTelephone(normalizedTelephone);
194	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
195	        owner.setEmail(normalizeEmail(owner.getEmail()));
196	        // Default the (optional) registration date to the server's current date when none was supplied.
197	        if (owner.getRegistrationDate() == null) {
198	            owner.setRegistrationDate(LocalDate.now());
199	        }
200	        // The effective registration date must fall on a business day: when it lands on a Saturday or
201	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
202	        // derived from the registration date below (daily create-limit, membership number) uses this
203	        // adjusted date.
204	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
205	        // Reject the request once the maximum number of owners for the owner's registration day has
206	        // been reached (100 or more owners already created on that date).
207	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
208	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
209	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
210	        }
211	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
212	        // owner's registration day at the moment this owner was created; otherwise clear it.
213	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
214	        // Reject the request when the owner's city has already reached its owner capacity.
215	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
216	            throw new CityCapacityException(owner.getCity());
217	        }
218	        // Resolve household membership before computing the identity key: when another owner already
219	        // shares the same last name and address (compared case-insensitively with collapsed
220	        // whitespace) and the caller opts in by setting 'sharesHousehold' true, assign a stable
221	        // shared 'householdId' to the new owner and backfill it onto every existing member that does
222	        // not yet carry it. The household is thus reflected in the owner's identity key.
223	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
224	        if (!householdMembers.isEmpty() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
225	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
226	            owner.setHouseholdId(householdId);
227	            for (Owner member : householdMembers) {
228	                if (!householdId.equals(member.getHouseholdId())) {
229	                    member.setHouseholdId(householdId);
230	                    this.clinicService.saveOwner(member);
231	                }
232	            }
233	        }
234	        // All duplicate detection is consolidated into this single derived identity key
235	        // ('<normalizedTelephone>|<email or empty>|<householdId or empty>'): reject with 409 only
236	        // when the new owner's WHOLE identity key exactly matches an existing owner's. Because the
237	        // telephone is part of the key, two members of the same household with different telephones
238	        // have different keys and are both allowed; only an exact full-key match is a duplicate.
239	        String identityKey = owner.getIdentityKey();
240	        boolean identityCollision = this.clinicService.findAllOwners().stream()
241	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
242	        if (identityCollision) {
243	            throw new DuplicateIdentityException(identityKey);
244	        }
245	        // Record how many existing owners already share this first name and last name
246	        // (compared case-insensitively) before this owner is created.
247	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
248	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
249	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
250	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
251	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
252	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
253	        this.clinicService.saveOwner(owner);
254	        populateHouseholdSize(owner);
255	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
256	        // Emit an audit line carrying the new owner's id, customer code, registration date
257	        // and numeric membership level.
258	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
259	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
260	            ownerDto.getMembershipLevel());
261	        headers.setLocation(UriComponentsBuilder.newInstance()
262	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
263	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
264	    }
