283	    /**
284	     * Populate the owner's household size: the number of owners sharing this owner's
285	     * {@code householdId} (including the owner itself). An owner with no household is a household
286	     * of one.
287	     *
288	     * @param owner the owner whose household size should be computed and set
289	     */
290	    private void populateHouseholdSize(Owner owner) {
291	        String householdId = owner.getHouseholdId();
292	        if (!StringUtils.hasText(householdId)) {
293	            owner.setHouseholdSize(1);
294	            return;
295	        }
296	        int size = (int) this.clinicService.findAllOwners().stream()
297	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
298	            .count();
299	        owner.setHouseholdSize(size);
300	    }
