302	    /**
303	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
304	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
305	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
306	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
307	     *
308	     * @param city     the owner's city
309	     * @param lastName the owner's last name
310	     * @return the generated customer code
311	     */
312	    private String generateCustomerCode(String city, String lastName) {
313	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
314	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
315	        String normalizedCity = normalizeForComparison(city);
316	        int sequence = (int) this.clinicService.findAllOwners().stream()
317	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
318	            .count() + 1;
319	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
320	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
321	    }
