323	    /**
324	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
325	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
326	     * that is stored, returned and used for every value derived from it.
327	     *
328	     * @param date the effective registration date (supplied or defaulted)
329	     * @return the same date when it is a weekday, otherwise the next Monday
330	     */
331	    private LocalDate rollToBusinessDay(LocalDate date) {
332	        DayOfWeek dayOfWeek = date.getDayOfWeek();
333	        if (dayOfWeek == DayOfWeek.SATURDAY) {
334	            return date.plusDays(2);
335	        }
336	        if (dayOfWeek == DayOfWeek.SUNDAY) {
337	            return date.plusDays(1);
338	        }
339	        return date;
340	    }
