342	    /**
343	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
344	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
345	     *
346	     * @param customerCode     the owner's already-assigned customer code
347	     * @param registrationDate the owner's registration date
348	     * @return the generated membership number
349	     */
350	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
351	        String yy = String.format("%02d", registrationDate.getYear() % 100);
352	        return String.format("%s-M%s", customerCode, yy);
353	    }
