400	    /**
401	     * Find the existing owners that live in the same household as the given values, i.e. those that
402	     * share both the last name and the address when each is compared case-insensitively with
403	     * collapsed whitespace.
404	     *
405	     * @param lastName the incoming owner's last name
406	     * @param address  the incoming owner's address
407	     * @return the matching existing owners (possibly empty)
408	     */
409	    private List<Owner> findHouseholdMembers(String lastName, String address) {
410	        String normalizedLastName = normalizeForComparison(lastName);
411	        String normalizedAddress = normalizeForComparison(address);
412	        return this.clinicService.findAllOwners().stream()
413	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
414	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
415	            .toList();
416	    }
