418	    /**
419	     * Generate a stable shared household identifier for the given last name and address. The value is
420	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
421	     * and address, so every owner joining the same household resolves to the same identifier. It is the
422	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
423	     *
424	     * @param lastName the household's last name
425	     * @param address  the household's address
426	     * @return the stable household identifier
427	     */
428	    private String generateHouseholdId(String lastName, String address) {
429	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
430	        try {
431	            byte[] digest = MessageDigest.getInstance("SHA-256")
432	                .digest(key.getBytes(StandardCharsets.UTF_8));
433	            StringBuilder sb = new StringBuilder(digest.length * 2);
434	            for (byte b : digest) {
435	                sb.append(String.format("%02x", b));
436	            }
437	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
438	        } catch (java.security.NoSuchAlgorithmException e) {
439	            throw new IllegalStateException("SHA-256 not available", e);
440	        }
441	    }
