443	    /**
444	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
445	     * single space, upper-case the result and expand common street-type abbreviations token by token
446	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
447	     * to the empty string. The result is the canonical form that is stored, returned and used for every
448	     * address comparison (household duplicate detection and the shared household id).
449	     *
450	     * @param address the raw address, may be {@code null}
451	     * @return the normalized address
452	     */
453	    private String normalizeAddress(String address) {
454	        if (address == null) {
455	            return "";
456	        }
457	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
458	        if (collapsed.isEmpty()) {
459	            return "";
460	        }
461	        String[] tokens = collapsed.split(" ");
462	        StringBuilder sb = new StringBuilder(collapsed.length());
463	        for (int i = 0; i < tokens.length; i++) {
464	            if (i > 0) {
465	                sb.append(' ');
466	            }
467	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
468	        }
469	        return sb.toString();
470	    }
471	
472	    /**
473	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
474	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
475	     *
476	     * @param value the raw value, may be {@code null}
477	     * @return the normalized value
478	     */
479	    private String normalizeForComparison(String value) {
480	        if (value == null) {
481	            return "";
482	        }
483	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
484	    }
