486	    /**
487	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
488	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
489	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
490	     * is returned lower-cased.
491	     *
492	     * @param email the raw email from the request payload, may be {@code null}
493	     * @return the lower-cased email, or {@code null} when none was provided
494	     */
495	    private String normalizeEmail(String email) {
496	        if (!StringUtils.hasText(email)) {
497	            return null;
498	        }
499	        if (!EMAIL_PATTERN.matcher(email).matches()) {
500	            throw new InvalidRequestException(List.of("email"));
501	        }
502	        return email.toLowerCase(Locale.ROOT);
503	    }
